def g(n):
    if n == 1:
        return 1
    # Prime factorization
    factors = {}
    temp_n = n
    d = 2
    while d * d <= temp_n:
        while temp_n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp_n //= d
        d += 1
    if temp_n > 1:
        factors[temp_n] = factors.get(temp_n, 0) + 1

    # h(n) = sum(v_p(n) / p)
    h_n = 0
    for p, v in factors.items():
        h_n += v / p

    # g(n) = n * (h(n) + 1)
    return n * (h_n + 1)

solutions = []
for n in range(1, 4001):
    if g(n) == 2 * n:
        solutions.append(n)

print(f"Solutions: {solutions}")

def g_recursive(n):
    if n == 1:
        return 1

    # Standard prime factorization
    factors = []
    temp_n = n
    d = 2
    while d * d <= temp_n:
        if temp_n % d == 0:
            factors.append((d, 1))
            temp_n //= d
            while temp_n % d == 0:
                factors[-1] = (d, factors[-1][1] + 1)
                temp_n //= d
        d += 1
    if temp_n > 1:
        factors.append((temp_n, 1))

    # We need g(p^k). g(p^k) = p*g(p^{k-1}) + p^{k-1}*g(p) - p^k
    # g(p) = p + 1

    def get_g_pk(p, k):
        if k == 1:
            return p + 1
        # g(p^k) = p*g(p^{k-1}) + p^{k-1}*g(p) - p^k
        # We can use the formula g(p^k) = p^k + k*p^{k-1}
        return p**k + k * (p**(k-1))

    # Use the property g(nm) = n*g(m) + m*g(n) - n*m
    # We can build it up for n = p1^a1 * p2^a2 * ...
    # Let's use a recursive approach to compute g(n) based on its prime factorization.

    def compute_g(factors_list):
        if not factors_list:
            return 1
        # f(n) = g(n) - n
        # f(nm) = n*f(m) + m*f(n)
        # f(p^k) = k*p^{k-1}

        # Let's use the property f(n) = n * sum(a_i/p_i)
        # g(n) = n + f(n) = n * (1 + sum(a_i/p_i))
        h_n = 0
        for p, a in factors_list:
            h_n += a / p
        return n * (1 + h_n)

    # Actually, let's just compute it directly.
    n_val = 1
    for p, a in factors:
        n_val *= (p**a)

    h_n = 0
    for p, a in factors:
        h_n += a / p
    return n_val * (1 + h_n)

