for n in [4, 27, 3125]:
    print(f"g({n}) = {g_recursive(n)}")

def find_all_solutions_large(limit):
    A = [0.0] * (limit + 1)
    for i in range(2, limit + 1):
        for p in range(2, int(i**0.5) + 1):
            if i % p == 0:
                A[i] = A[i // p] + 1/p
                break
        else:
            A[i] = 1/i

    res = []
    for i in range(1, limit + 1):
        if abs(A[i] - 1.0) < 1e-9:
            res.append(i)
    return res

print(find_all_solutions_large(100000))

